WITH department_summary AS (SELECT dept_id, SORT_ARRAY(COLLECT_SET(level)) AS level_list, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) AS job_title_values FROM employees GROUP BY dept_id) SELECT d.budget, ds.level_list, ds.job_title_values FROM departments d JOIN department_summary ds ON d.id = ds.dept_id
